/**
 * Data management, on `src/api/schema.d.ts` — generated by `make types` and held
 * to the tree by `make lint-generated`.
 *
 * `DataView` hand-declared both, and both got the optionality backwards:
 * `counts`, `preserved` and `deleted` are all optional on the models and were
 * declared required. On this screen specifically that matters more than usual --
 * it is the one that DELETES, and a view that assumes `deleted` is always
 * present would render "Deleted undefined rows" at exactly the moment the reader
 * needs to know what happened.
 *
 * See contract C9 on generated artifacts.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

/**
 * `GET /data/stats` — what Venona is holding, by table.
 *
 * `preserved` is the list of tables a purge does NOT touch, which is the half of
 * this screen that makes the other half safe to press.
 */
export type DataStats = Schemas['DataStats']

/** `POST /data/purge`. `graph_cleared` reports whether Neo4j went with it —
 *  it can be false while the purge succeeded, since the projection is
 *  rebuildable and its absence is not a failure (invariant 1). */
export type PurgeResult = Schemas['PurgeResult']

/** `GET /data/exports`. A row can outlive the file it names, so the screen
 *  turns on `download_url`, which the server fills in only where the file is
 *  still there. */
export type DataExportList = Schemas['DataExportList']
export type DataExport = Schemas['DataExport']
